"""Kitchen Sink page: ColumnView, a Finder-style browser: each node's children open in the
next column, and a leaf shows a preview (a Label of this form, its PreviewWidget); with
FileSystem it browses folders and files."""

from vp6 import *

FACTS = {"lion": "Lives in prides on the savanna", "tiger": "The largest cat",
         "wolf": "Hunts in packs", "fox": "Eats nearly anything",
         "oak": "Lives for centuries", "fern": "Older than the dinosaurs",
         "rose": "Has thorns, not spines"}


class pgColumns(Form):
    # region VP6 Designer - generated by the form designer, do not edit
    def InitializeComponent(self):
        self.Caption = 'ColumnView'
        self.Width = 640
        self.Height = 440
        self.cvwNature = ColumnView(self, Left=16, Top=16, Width=608, Height=200,
                                    Items=['Animals|animals', '    Cats|cats', '        Lion|lion', '        Tiger|tiger', '    Dogs|dogs', '        Wolf|wolf', '        Fox|fox', 'Plants|plants', '    Trees|trees', '        Oak|oak', '    Fern|fern', '    Rose|rose'],
                                    PreviewWidget='lblPreview', TabIndex=1)
        self.lblPreview = Label(self, Caption='(the preview)', Left=474, Top=224, Width=150,
                                Height=22, WordWrap=True, TabIndex=2)
        self.lblNode = Label(self, Caption='Choose an animal or a plant', Left=16, Top=224,
                             Width=450, Height=22, TabIndex=3)
        self.cvwFiles = ColumnView(self, Left=16, Top=256, Width=608, Height=140, FileSystem=True,
                                   Path='.', TabIndex=4,
                                   ToolTipText="FileSystem: this project's folder")
        self.lblFile = Label(self, Caption='', Left=16, Top=404, Width=608, Height=22, TabIndex=5)
    # endregion

    def cvwNature_NodeClick(self, Node):
        self.lblNode.Caption = f"NodeClick: {Node.FullPath}"
        if not Node.IsFolder:  # a leaf: the preview column shows the Label
            self.lblPreview.Caption = f"{Node.Text}\n{FACTS.get(Node.Key, '')}"

    def cvwNature_Expand(self, Node):
        self.lblNode.Caption = f"Expand: {Node.Text} has {Node.Children} children"

    def cvwFiles_NodeClick(self, Node):
        kind = "folder" if Node.IsFolder else "file"
        self.lblFile.Caption = f"The {kind} {self.cvwFiles.SelectedPath}"


if __name__ == "__main__":
    run(pgColumns)
